head.script:
// 상장관련공통함수
scwin.gDate;

// 상장원부 검토승인

scwin.clickBzProcsNo; // 업무처리번호
scwin.clickIsuCd; // 종목코드
scwin.clickIsuNm; // 종목명
scwin.clickProcsStatCd; // 상태코드값
scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 가우스헤더 셋팅
        // dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
        // dts_StudyCond.reset();
        scwin.setCode();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        scwin.clickBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
        scwin.clickIsuCd = dts_List.getCellData(row, "ISU_CD");
        scwin.clickIsuNm = dts_List.getCellData(row, "ISU_KOR_NM");
        scwin.clickProcsStatCd = dts_List.getCellData(row, "PROCS_STAT_CD");
        const options = {
            id: "ULDSTF70032P",
            title: "상장원부(수정요청)",
            type: "browserPopup",
            width: "800px",
            height: "800px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("/digital/ULDSTF70032P.gfm", options);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        // 조회
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF70032.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF70032.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, {fileName: " 상장원부 검토승인 목록", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_SearchIsu_onclick
 * @description img_SearchIsu 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SearchIsu_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;
        $c.lcd.fn_PopFindDigitalIsuAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.img_SearchIsu_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onchange
 * @description txb_ISU_CD 변경 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onchange = function() {
    try {
        txb_ISU_NM.setValue("");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF70032.txb_ISU_CD_onchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const srchIsuCd = txb_ISU_CD.getValue();
    // url += "&LD_MKT_TP=" + fr_MktId;
    url += "&ISU_CD=" + srchIsuCd;
    url += "&STRT_DD=" + edt_SDate.getValue();
    url += "&END_DD=" + edt_EDate.getValue();
    url += "&LIST_PROCS_STAT=" + cmb_PROCS_STAT_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/digital/DigitalListinvstg.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description 상장신청인 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_ISU_NM.getValue(); // 명칭값을 포함할 컨트롤
    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setParIsur = function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
    }
};

/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    edt_SDate.setValue('19000101');
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};
